(6888297, 1038389, 114225, '<td valign="top">I really really enjoy the way you did this. So many of these types of photo don''t have character, but the way you composed this and created a scene that looks like it was painted is just magnificent.</td>', 'I really really enjoy the way you did this. So many of these types of photo don''t have character, but the way you composed this and created a scene that looks like it was painted is just magnificent.', '2012-10-22 11:20:17.000000', NULL, 1),
(6888298, 1038498, 114225, '<td valign="top">Hard to tell, this looks like it may actually be refraction, but I will give you the benefit of the doubt.</td>', 'Hard to tell, this looks like it may actually be refraction, but I will give you the benefit of the doubt.', '2012-10-22 11:20:57.000000', NULL, 1),
(6888299, 1038483, 114225, '<td valign="top">Nice unique take on this challenge. I like the high key effect.</td>', 'Nice unique take on this challenge. I like the high key effect.', '2012-10-22 11:21:14.000000', NULL, 1),
(6888300, 1038197, 114225, '<td valign="top">Well done. Perfect way to fool someone, until they examine the details.<br/> <br/>However, I''m not a fan of the harsh details from what I assume is post processing.</td>', 'Well done. Perfect way to fool someone, until they examine the details. However, I''m not a fan of the harsh details from what I assume is post processing.', '2012-10-22 11:22:14.000000', NULL, 1),
(6888301, 1038208, 114225, '<td valign="top">Wow, that is creative I wonder how long it took you to get the angles exactly right.</td>', 'Wow, that is creative I wonder how long it took you to get the angles exactly right.', '2012-10-22 11:23:24.000000', NULL, 1),
(6888302, 1037933, 114225, '<td valign="top">What a cute little guy. I like how you got nice and close.</td>', 'What a cute little guy. I like how you got nice and close.', '2012-10-22 11:23:42.000000', NULL, 1),
