(6888596, 1038473, 94815, '<td valign="top">Hard to find among so many balconies. Oops... it was Juliette on the balcony. 7 anyway.</td>', 'Hard to find among so many balconies. Oops... it was Juliette on the balcony. 7 anyway.', '2012-10-22 17:10:26.000000', NULL, 1),
(6888597, 1037933, 94815, '<td valign="top">Do box turtles swim? I can''t remember. Nice shot. 7</td>', 'Do box turtles swim? I can''t remember. Nice shot. 7', '2012-10-22 17:10:41.000000', NULL, 1),
(6888598, 1038219, 93171, '<td valign="top">Clever title!</td>', 'Clever title!', '2012-10-22 17:11:16.000000', NULL, 1),
(6888599, 1038148, 94815, '<td valign="top">Eyecatching capture. Two headed lady or Rembrandt in a parallel dimension. Maybe more tremulo than glissando. Now who haunts art museums in NYC? 7</td>', 'Eyecatching capture. Two headed lady or Rembrandt in a parallel dimension. Maybe more tremulo than glissando. Now who haunts art museums in NYC? 7', '2012-10-22 17:11:22.000000', NULL, 1),
