(6888606, 1038152, 94815, '<td valign="top">Bullseye. Or girlseye (I know I"m silly). 8</td>', 'Bullseye. Or girlseye (I know I"m silly). 8', '2012-10-22 17:23:12.000000', NULL, 1),
