(6890012, 1038207, 114225, '<td valign="top">Interesting image. So many shadowy figures. The more I look, the more I see!</td>', 'Interesting image. So many shadowy figures. The more I look, the more I see!', '2012-10-24 11:25:41.000000', NULL, 1),
(6890014, 1038379, 149433, '<td valign="top">The greyish colour destroys any feeling of reflection...</td>', 'The greyish colour destroys any feeling of reflection...', '2012-10-24 11:26:50.000000', NULL, 1),
(6890017, 1038170, 47316, '<td valign="top">Lovely. I enjoy the circle created and the fairytale like quality of this.</td>', 'Lovely. I enjoy the circle created and the fairytale like quality of this.', '2012-10-24 11:30:23.000000', NULL, 1),
(6890018, 1038169, 47316, '<td valign="top">It is an interesting subject but I don''t think the composition does much for it.</td>', 'It is an interesting subject but I don''t think the composition does much for it.', '2012-10-24 11:31:34.000000', NULL, 1),
(6890019, 1038389, 47316, '<td valign="top">Pretty colors.</td>', 'Pretty colors.', '2012-10-24 11:31:51.000000', NULL, 1),
