(6890068, 1038113, 114225, '<td valign="top">Indeed a reflection (in your phone, it looks like), but other than that it really doesn''t interest me photographically.</td>', 'Indeed a reflection (in your phone, it looks like), but other than that it really doesn''t interest me photographically.', '2012-10-24 12:35:20.000000', NULL, 1),
(6890069, 1038448, 114225, '<td valign="top">I feel that this photo could have been so much better without the lensbaby effect. The stones and barren tree already tells a story.</td>', 'I feel that this photo could have been so much better without the lensbaby effect. The stones and barren tree already tells a story.', '2012-10-24 12:36:01.000000', NULL, 1),
