(6890794, 1038395, 138630, '<td valign="top">Graphically clever - black and white is the choice.  Would it be better if the background was clean white?  Voted earlier.</td>', 'Graphically clever - black and white is the choice.  Would it be better if the background was clean white?  Voted earlier.', '2012-10-25 11:09:01.000000', NULL, 1),
(6890796, 1038097, 138630, '<td valign="top">Pretty scene, love the sunburst.  Sky looks a bit grainy and colors, esp the reds, just a hair too saturated for me.  Lovely wispy clouds in the sky though.  Voted earlier.</td>', 'Pretty scene, love the sunburst.  Sky looks a bit grainy and colors, esp the reds, just a hair too saturated for me.  Lovely wispy clouds in the sky though.  Voted earlier.', '2012-10-25 11:10:13.000000', NULL, 1),
(6890797, 1038494, 138630, '<td valign="top">Very nice autumn colors and lovely clarity.  Voted earlier.</td>', 'Very nice autumn colors and lovely clarity.  Voted earlier.', '2012-10-25 11:10:37.000000', NULL, 1),
(6890800, 1038094, 138630, '<td valign="top">Beautiful scene, enhanced IMO by the inclusion of the bit of boardwalk that invites me into it.  For my taste, colors are a little strong esp the reds as is the HDR like treatment.  Voted earlier.</td>', 'Beautiful scene, enhanced IMO by the inclusion of the bit of boardwalk that invites me into it.  For my taste, colors are a little strong esp the reds as is the HDR like treatment.  Voted earlier.', '2012-10-25 11:16:19.000000', NULL, 1),
