(6892945, 1038207, 113278, '<td valign="top">This is incredible. Love how you did this. <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1028934" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/110000-114999/113278/120/Copyrighted_Image_Reuse_Prohibited_1028934.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/110000-114999/113278/120/Copyrighted_Image_Reuse_Prohibited_1028934.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/110000-114999/113278/120/Copyrighted_Image_Reuse_Prohibited_1028934.jpg"/></a></td>', 'This is incredible. Love how you did this.  ', '2012-10-28 17:03:59.000000', NULL, 1),
(6892976, 1038178, 104230, '<td valign="top">Interesting image.  I like how the branches'' reflections look like roots.  There is a slight feeling of disjointedness between that rather busy "slice" at the top and the reflection, not helped by the line caused by the edge of whatever is holding the water. I like that some of the water appears relatively calm while some areas have ripples.</td>', 'Interesting image.  I like how the branches'' reflections look like roots.  There is a slight feeling of disjointedness between that rather busy "slice" at the top and the reflection, not helped by the line caused by the edge of whatever is holding the water. I like that some of the water appears relatively calm while some areas have ripples.', '2012-10-28 18:43:08.000000', NULL, 1),
(6892977, 1038389, 104230, '<td valign="top">Lovely. Beautiful colors and I like how my eye is lead through the image from the lower left to that patch of blue in the upper right.</td>', 'Lovely. Beautiful colors and I like how my eye is lead through the image from the lower left to that patch of blue in the upper right.', '2012-10-28 18:45:55.000000', NULL, 1),
(6892979, 1038091, 104230, '<td valign="top">I really like these types of images. This beautifully takes advantage of the ripples in the water. Well seen.<br/><br/><i>Message edited by author 2012-10-29 00:07:43.</i></td>', 'I really like these types of images. This beautifully takes advantage of the ripples in the water. Well seen.', '2012-10-28 18:49:01.000000', '2012-10-29 00:07:43.000000', 1),
(6892980, 1038473, 104230, '<td valign="top">Well seen. I like this kind of abstract image and the black and white works well.</td>', 'Well seen. I like this kind of abstract image and the black and white works well.', '2012-10-28 18:52:31.000000', NULL, 1),
(6892981, 1038211, 114285, '<td valign="top">I like the Monet feel to this, but the PP is just a little too saturated.<br/> <br/>Still love the Autumn tones in the water.</td>', 'I like the Monet feel to this, but the PP is just a little too saturated. Still love the Autumn tones in the water.', '2012-10-28 18:54:08.000000', NULL, 1),
(6893006, 1038207, 104230, '<td valign="top">Very creative and appealing. Well done.</td>', 'Very creative and appealing. Well done.', '2012-10-28 19:56:58.000000', NULL, 1),
(6893008, 1038111, 104230, '<td valign="top">Lovely rich colors, and detail.</td>', 'Lovely rich colors, and detail.', '2012-10-28 19:59:10.000000', NULL, 1),
