(6893022, 1038016, 109227, '<td valign="top">Nice creative shot.</td>', 'Nice creative shot.', '2012-10-28 20:28:45.000000', NULL, 1),
(6893023, 1038208, 40391, '<td valign="top">Great idea and nicely aligned.  I quite like the high key result.</td>', 'Great idea and nicely aligned.  I quite like the high key result.', '2012-10-28 20:34:36.000000', NULL, 1),
(6893030, 1038219, 40391, '<td valign="top">I see it. Great imagination! Nice colours too.</td>', 'I see it. Great imagination! Nice colours too.', '2012-10-28 20:41:20.000000', NULL, 1),
(6893032, 1038482, 114285, '<td valign="top">I really don''t see many reflections here in this shot apart from the clouds, and they aren''t all that interesting, but despite that it is a pretty scene.</td>', 'I really don''t see many reflections here in this shot apart from the clouds, and they aren''t all that interesting, but despite that it is a pretty scene.', '2012-10-28 20:52:20.000000', NULL, 1),
(6893039, 1038101, 114285, '<td valign="top">Picture perfect scene, already voted.</td>', 'Picture perfect scene, already voted.', '2012-10-28 21:18:10.000000', NULL, 1),
(6893041, 1038473, 114285, '<td valign="top">looks like a hotel balcony reflection in the water, very clever, bumping up~</td>', 'looks like a hotel balcony reflection in the water, very clever, bumping up~', '2012-10-28 21:22:20.000000', NULL, 1),
(6893042, 1038432, 114285, '<td valign="top">I love the blue tones in the water, great reflections, but seems a little dark and contrasty, still bumping up, b/c it does have visual appeal!~</td>', 'I love the blue tones in the water, great reflections, but seems a little dark and contrasty, still bumping up, b/c it does have visual appeal!~', '2012-10-28 21:25:58.000000', NULL, 1),
