(6893056, 1037808, 67697, '<td valign="top">So crisp and pretty.  Gorgeous job on the lighting.</td>', 'So crisp and pretty.  Gorgeous job on the lighting.', '2012-10-28 22:46:58.000000', NULL, 1),
