(6893059, 1038170, 67697, '<td valign="top">Almost a complete circle!  So pretty.  Love that mist.</td>', 'Almost a complete circle!  So pretty.  Love that mist.', '2012-10-28 22:47:48.000000', NULL, 1),
(6893060, 1038207, 67697, '<td valign="top">It''s like a game - how many shadows are there?  A very cool little puzzle.</td>', 'It''s like a game - how many shadows are there?  A very cool little puzzle.', '2012-10-28 22:48:24.000000', NULL, 1),
(6893061, 1038393, 67697, '<td valign="top">I like this and can''t really explain why.  I think it''s the simplicity that makes it so intriguing.</td>', 'I like this and can''t really explain why.  I think it''s the simplicity that makes it so intriguing.', '2012-10-28 22:48:56.000000', NULL, 1),
(6893063, 1038445, 67697, '<td valign="top">What a beautiful day for a photo.  That reflection is gorgeous.</td>', 'What a beautiful day for a photo.  That reflection is gorgeous.', '2012-10-28 22:49:21.000000', NULL, 1),
(6893064, 1038002, 67697, '<td valign="top">Shots from this area are always so pretty.  I love that sky and the sunset is beautiful.</td>', 'Shots from this area are always so pretty.  I love that sky and the sunset is beautiful.', '2012-10-28 22:50:03.000000', NULL, 1),
(6893065, 1038494, 67697, '<td valign="top">This kind of sums up our autumn here.  Love those colors.</td>', 'This kind of sums up our autumn here.  Love those colors.', '2012-10-28 22:50:32.000000', NULL, 1),
(6893066, 1038171, 67697, '<td valign="top">I love reflection shots that have a story within a story.  So many things to see.  Looks like something interesting has caught that man''s eye :)</td>', 'I love reflection shots that have a story within a story.  So many things to see.  Looks like something interesting has caught that man''s eye :)', '2012-10-28 22:51:23.000000', NULL, 1),
