(6893329, 1038483, 63812, '<td valign="top">Beautiful. Congrats on 5th place!!</td>', 'Beautiful. Congrats on 5th place!!', '2012-10-29 05:45:46.000000', NULL, 0),
(6893332, 1038152, 28742, '<td valign="top">Congratulations! Well done.</td>', 'Congratulations! Well done.', '2012-10-29 05:51:17.000000', NULL, 0),
(6893333, 1038483, 49511, '<td valign="top">Without the clothes the rest of your body would have reflected also and added to the wow factor, gave you an 8 as it is; a very cool picture</td>', 'Without the clothes the rest of your body would have reflected also and added to the wow factor, gave you an 8 as it is; a very cool picture', '2012-10-29 05:55:24.000000', NULL, 0),
(6893334, 1038091, 28742, '<td valign="top">5.7 isn''t bad, but I woulda hoped for a 6 with this. It''s very good. Maybe if you punched up the brightness &amp; contrast a bit. It is a tad dark. Well done, though.</td>', '5.7 isn''t bad, but I woulda hoped for a 6 with this. It''s very good. Maybe if you punched up the brightness & contrast a bit. It is a tad dark. Well done, though.', '2012-10-29 05:58:51.000000', NULL, 0),
(6893344, 1038455, 12611, '<td valign="top">I am fascinated by this shot.  I keep going back from the reflection to reality, suspending disbelief that he didn''t get wet...</td>', 'I am fascinated by this shot.  I keep going back from the reflection to reality, suspending disbelief that he didn''t get wet...', '2012-10-29 06:34:03.000000', NULL, 0),
(6893345, 1038207, 12611, '<td valign="top">The grain and muted tones are superb, but thank especially for the explanation.  It was hurting my head trying to logically figure it out.</td>', 'The grain and muted tones are superb, but thank especially for the explanation.  It was hurting my head trying to logically figure it out.', '2012-10-29 06:37:19.000000', NULL, 0),
(6893347, 1038152, 52549, '<td valign="top">Excellent image. Many congrats on your first ribbon. It''s so well deserved.</td>', 'Excellent image. Many congrats on your first ribbon. It''s so well deserved.', '2012-10-29 06:53:45.000000', NULL, 0),
