(6893416, 1038207, 20799, '<td valign="top">Fabulous shot Mark, I loved it.</td>', 'Fabulous shot Mark, I loved it.', '2012-10-29 09:40:39.000000', NULL, 0),
(6893430, 1038148, 19825, '<td valign="top">You picked correctly for my taste. I love the outer framing and the interesting connection between the three figures. The woman appears to be looking at both figures, and the two figures are slightly facing each other but both staring back at her. No one captures interesting interactions between people and art quite like you. Please let me know when the coffee table book collection of these goes into print. Congratulations on the PH bling.</td>', 'You picked correctly for my taste. I love the outer framing and the interesting connection between the three figures. The woman appears to be looking at both figures, and the two figures are slightly facing each other but both staring back at her. No one captures interesting interactions between people and art quite like you. Please let me know when the coffee table book collection of these goes into print. Congratulations on the PH bling.', '2012-10-29 10:06:05.000000', NULL, 0),
